-- X-UI v1 M3 (DATA_MODEL §10): the transaction ledger — transactions (headers), transaction_events
-- (immutable versions), transaction_entries (immutable account movements) and
-- ledger_idempotency_keys (complete results of financial writes). Generated by drizzle-kit, then
-- edited by hand (test/migrations-guard.test.ts, test/m3-schema.test.ts and test/m3-db-probe.test.ts
-- check the result on libsql and on D1):
--   * partial index WHERE clause: "transaction_entries"."txn_type" written as `txn_type`, as in DATA_MODEL.
--   * the 21 hand-written triggers of DATA_MODEL §10.7.2 at the end (drizzle has no trigger API),
--     created in the order that makes SQLite run the checks of each group in the documented order.
-- Only creates the four M3 tables, their indexes and triggers: no M1 / M2 table is touched.
CREATE TABLE `ledger_idempotency_keys` (
	`user_id` text NOT NULL,
	`key` text NOT NULL,
	`operation` text NOT NULL,
	`request_hash` text NOT NULL,
	`hash_version` integer NOT NULL,
	`op_id` text NOT NULL,
	`transaction_id` text NOT NULL,
	`result_revision` integer NOT NULL,
	`result_event_id` text NOT NULL,
	`audit_id` text NOT NULL,
	`response_status` integer NOT NULL,
	`created_at` integer NOT NULL,
	`expires_at` integer,
	PRIMARY KEY(`user_id`, `key`),
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`transaction_id`,`user_id`) REFERENCES `transactions`(`id`,`user_id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`result_event_id`,`user_id`) REFERENCES `transaction_events`(`id`,`user_id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "ledger_idempotency_keys_key_ck" CHECK(length(key) BETWEEN 16 AND 64 AND key NOT GLOB '*[^0-9A-Za-z_-]*'),
	CONSTRAINT "ledger_idempotency_keys_operation_ck" CHECK(operation IN ('transaction.create', 'transaction.correct', 'transaction.void')),
	CONSTRAINT "ledger_idempotency_keys_hash_ck" CHECK(length(request_hash) = 64 AND request_hash NOT GLOB '*[^0-9a-f]*'),
	CONSTRAINT "ledger_idempotency_keys_hash_version_ck" CHECK(typeof(hash_version) = 'integer' AND hash_version >= 1),
	CONSTRAINT "ledger_idempotency_keys_result_revision_ck" CHECK(typeof(result_revision) = 'integer' AND result_revision >= 1),
	CONSTRAINT "ledger_idempotency_keys_response_status_ck" CHECK(response_status IN (200, 201)),
	CONSTRAINT "ledger_idempotency_keys_retention_ck" CHECK((operation = 'transaction.create') = (expires_at IS NULL)),
	CONSTRAINT "ledger_idempotency_keys_expires_ck" CHECK(expires_at IS NULL OR expires_at > created_at)
);
--> statement-breakpoint
CREATE INDEX `ledger_idempotency_keys_user_expires_idx` ON `ledger_idempotency_keys` (`user_id`,`expires_at`);--> statement-breakpoint
