	CONSTRAINT "transaction_events_merchant_scope_rule_ck" CHECK(merchant_scope IS NULL OR merchant_scope = CASE WHEN merchant_country IS NULL THEN 'unknown' WHEN merchant_country = home_region THEN 'domestic' ELSE 'foreign' END)
);
