CREATE TABLE `transactions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`txn_type` text NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`current_revision` integer DEFAULT 0 NOT NULL,
	`notes` text,
