	CONSTRAINT "transactions_status_ck" CHECK(status IN ('active', 'voided')),
	CONSTRAINT "transactions_revision_ck" CHECK(typeof(current_revision) = 'integer' AND current_revision >= 0),
	CONSTRAINT "transactions_voided_at_ck" CHECK((status = 'voided') = (voided_at IS NOT NULL)),
	CONSTRAINT "transactions_voided_op_ck" CHECK((status = 'voided') = (voided_op_id IS NOT NULL)),
	CONSTRAINT "transactions_void_reason_ck" CHECK(void_reason IS NULL OR status = 'voided'),
	CONSTRAINT "transactions_published_ck" CHECK(status = 'active' OR current_revision >= 1)
);
