-- ---------------------------------------------------------------- transactions (header)
-- Order matters: SQLite runs the BEFORE triggers of one table and event newest-first (verified on
-- libsql and D1 by test/m3-db-probe.test.ts), so each group below is created in reverse of the order
-- its checks run in: tx_update_guard, then C2, C3, C5, C6, C7 (DATA_MODEL §10.7.3).
-- C1: a header is inserted unpublished (revision 0), active and without void data (§10.10 S1).
CREATE TRIGGER `tx_insert_guard` BEFORE INSERT ON `transactions`
FOR EACH ROW WHEN NEW.`current_revision` IS NOT 0 OR NEW.`status` IS NOT 'active' OR NEW.`voided_at` IS NOT NULL OR NEW.`voided_op_id` IS NOT NULL OR NEW.`void_reason` IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_HEADER_INSERT: a transaction header is inserted unpublished (current_revision 0), active and not voided');
END;--> statement-breakpoint
-- C7 (P2): a confirmed purely domestic version is never published.
CREATE TRIGGER `tx_publish_domestic` BEFORE UPDATE OF `current_revision` ON `transactions`
FOR EACH ROW WHEN OLD.`status` = 'active' AND NEW.`status` = 'active' AND NEW.`current_revision` = OLD.`current_revision` + 1
  AND NEW.`id` IS OLD.`id` AND NEW.`user_id` IS OLD.`user_id` AND NEW.`txn_type` IS OLD.`txn_type` AND NEW.`created_at` IS OLD.`created_at`
  AND NEW.`notes` IS OLD.`notes` AND NEW.`voided_at` IS OLD.`voided_at` AND NEW.`void_reason` IS OLD.`void_reason` AND NEW.`voided_op_id` IS OLD.`voided_op_id`
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_CONFIRMED_DOMESTIC: a confirmed purely domestic version is not recorded')
  FROM `transaction_events` ev
  WHERE ev.`transaction_id` = NEW.`id` AND ev.`user_id` = NEW.`user_id` AND ev.`revision` = NEW.`current_revision` AND ev.`foreign_status` = 'domestic';
END;--> statement-breakpoint
-- C6: re-derive the classification (v1, DATA_MODEL §10.8) from the saved snapshots only. Unknown
-- sides are NULL and never compared with <> alone. Only classifier_version 1 exists.
CREATE TRIGGER `tx_publish_classification` BEFORE UPDATE OF `current_revision` ON `transactions`
FOR EACH ROW WHEN OLD.`status` = 'active' AND NEW.`status` = 'active' AND NEW.`current_revision` = OLD.`current_revision` + 1
  AND NEW.`id` IS OLD.`id` AND NEW.`user_id` IS OLD.`user_id` AND NEW.`txn_type` IS OLD.`txn_type` AND NEW.`created_at` IS OLD.`created_at`
  AND NEW.`notes` IS OLD.`notes` AND NEW.`voided_at` IS OLD.`voided_at` AND NEW.`void_reason` IS OLD.`void_reason` AND NEW.`voided_op_id` IS OLD.`voided_op_id`
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_CLASSIFICATION: the saved classification does not follow from the saved snapshots')
  FROM (
    SELECT ev.`home_region` AS h, ev.`merchant_country` AS m, ev.`foreign_status` AS fs, ev.`transfer_scope` AS ts, ev.`classifier_version` AS cv,
           coalesce(o.`funding_account_country`, i.`funding_account_country`) AS a,
           coalesce(o.`funding_account_country`, ev.`counterparty_country`) AS f,
           coalesce(i.`funding_account_country`, ev.`counterparty_country`) AS t
    FROM `transaction_events` ev
    LEFT JOIN `transaction_entries` o ON o.`event_id` = ev.`id` AND o.`direction` = 'out'
    LEFT JOIN `transaction_entries` i ON i.`event_id` = ev.`id` AND i.`direction` = 'in'
    WHERE ev.`transaction_id` = NEW.`id` AND ev.`user_id` = NEW.`user_id` AND ev.`revision` = NEW.`current_revision`
  ) x
  WHERE x.cv IS NOT 1 OR CASE WHEN NEW.`txn_type` IN ('merchant_spend', 'merchant_refund') THEN
      x.fs IS NOT (CASE WHEN (x.a IS NOT NULL AND x.a <> x.h) OR (x.m IS NOT NULL AND x.m <> x.h) THEN 'foreign' WHEN x.m IS NULL THEN 'undetermined' ELSE 'domestic' END)
    ELSE
      x.fs IS NOT (CASE WHEN (x.f IS NOT NULL AND x.f <> x.h) OR (x.t IS NOT NULL AND x.t <> x.h) THEN 'foreign' WHEN x.f IS NOT NULL AND x.t IS NOT NULL THEN 'domestic' ELSE 'undetermined' END)
      OR x.ts IS NOT (CASE
        WHEN x.f IS NULL THEN (CASE WHEN x.t = x.h THEN 'unknown_to_domestic' ELSE 'unknown_to_foreign' END)
        WHEN x.t IS NULL THEN (CASE WHEN x.f = x.h THEN 'domestic_to_unknown' ELSE 'foreign_to_unknown' END)
        WHEN x.f = x.h AND x.t = x.h THEN 'domestic_local'
        WHEN x.f = x.h THEN 'outbound'
        WHEN x.t = x.h THEN 'inbound'
        WHEN x.t = x.f THEN 'foreign_local'
        ELSE 'foreign_cross_border' END)
    END;
END;--> statement-breakpoint
-- C5 (P8): an event amount may be missing only for money received from a third party.
CREATE TRIGGER `tx_publish_event_amount` BEFORE UPDATE OF `current_revision` ON `transactions`
FOR EACH ROW WHEN OLD.`status` = 'active' AND NEW.`status` = 'active' AND NEW.`current_revision` = OLD.`current_revision` + 1
  AND NEW.`id` IS OLD.`id` AND NEW.`user_id` IS OLD.`user_id` AND NEW.`txn_type` IS OLD.`txn_type` AND NEW.`created_at` IS OLD.`created_at`
  AND NEW.`notes` IS OLD.`notes` AND NEW.`voided_at` IS OLD.`voided_at` AND NEW.`void_reason` IS OLD.`void_reason` AND NEW.`voided_op_id` IS OLD.`voided_op_id`
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_EVENT_AMOUNT: the event amount may only be unknown for an incoming third-party transfer')
  FROM `transaction_events` ev
  WHERE ev.`transaction_id` = NEW.`id` AND ev.`user_id` = NEW.`user_id` AND ev.`revision` = NEW.`current_revision` AND ev.`event_amount` IS NULL
    AND (NEW.`txn_type` <> 'third_party_transfer' OR EXISTS (SELECT 1 FROM `transaction_entries` en WHERE en.`event_id` = ev.`id` AND en.`direction` = 'out'));
END;--> statement-breakpoint
-- C3: an own transfer has two registered sides and no counterparty, or one side and the other
-- (unregistered) side's jurisdiction.
CREATE TRIGGER `tx_publish_own_shape` BEFORE UPDATE OF `current_revision` ON `transactions`
FOR EACH ROW WHEN OLD.`status` = 'active' AND NEW.`status` = 'active' AND NEW.`current_revision` = OLD.`current_revision` + 1
  AND NEW.`id` IS OLD.`id` AND NEW.`user_id` IS OLD.`user_id` AND NEW.`txn_type` IS OLD.`txn_type` AND NEW.`created_at` IS OLD.`created_at`
  AND NEW.`notes` IS OLD.`notes` AND NEW.`voided_at` IS OLD.`voided_at` AND NEW.`void_reason` IS OLD.`void_reason` AND NEW.`voided_op_id` IS OLD.`voided_op_id`
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_OWN_TRANSFER_SHAPE: an own transfer has two entries and no counterparty, or one entry and the counterparty country')
  FROM `transaction_events` ev
  WHERE NEW.`txn_type` = 'own_transfer' AND ev.`transaction_id` = NEW.`id` AND ev.`user_id` = NEW.`user_id` AND ev.`revision` = NEW.`current_revision`
    AND (((SELECT count(*) FROM `transaction_entries` en WHERE en.`event_id` = ev.`id`) = 2)
          IS NOT (ev.`counterparty_country` IS NULL AND ev.`counterparty_name` IS NULL AND ev.`counterparty_institution` IS NULL AND ev.`counterparty_account_hint` IS NULL)
      OR ((SELECT count(*) FROM `transaction_entries` en WHERE en.`event_id` = ev.`id`) = 1 AND ev.`counterparty_country` IS NULL));
END;--> statement-breakpoint
-- C2: at least one entry, an own transfer at most two (other types: at most one, by index).
CREATE TRIGGER `tx_publish_entry_count` BEFORE UPDATE OF `current_revision` ON `transactions`
FOR EACH ROW WHEN OLD.`status` = 'active' AND NEW.`status` = 'active' AND NEW.`current_revision` = OLD.`current_revision` + 1
  AND NEW.`id` IS OLD.`id` AND NEW.`user_id` IS OLD.`user_id` AND NEW.`txn_type` IS OLD.`txn_type` AND NEW.`created_at` IS OLD.`created_at`
  AND NEW.`notes` IS OLD.`notes` AND NEW.`voided_at` IS OLD.`voided_at` AND NEW.`void_reason` IS OLD.`void_reason` AND NEW.`voided_op_id` IS OLD.`voided_op_id`
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_ENTRY_COUNT: a published version has at least one entry (an own transfer at most two)')
  FROM (SELECT count(*) AS n FROM `transaction_entries` en JOIN `transaction_events` ev ON ev.`id` = en.`event_id`
        WHERE ev.`transaction_id` = NEW.`id` AND ev.`user_id` = NEW.`user_id` AND ev.`revision` = NEW.`current_revision`) c
  WHERE c.n < 1 OR (NEW.`txn_type` = 'own_transfer' AND c.n > 2);
END;--> statement-breakpoint
-- Every UPDATE of a header (no OF, no WHEN) is one of: (1) notes only, any status, (2) publish
-- r -> r+1 of an active transaction, (3) void once. Each may also set updated_at. Codes in order:
-- identity columns -> LEDGER_HEADER_IMMUTABLE, anything but notes on a voided transaction ->
-- LEDGER_VOIDED, any other update -> LEDGER_REVISION_ORDER.
CREATE TRIGGER `tx_update_guard` BEFORE UPDATE ON `transactions`
FOR EACH ROW
BEGIN
  SELECT CASE
    WHEN NEW.`id` IS NOT OLD.`id` OR NEW.`user_id` IS NOT OLD.`user_id` OR NEW.`txn_type` IS NOT OLD.`txn_type` OR NEW.`created_at` IS NOT OLD.`created_at`
