CREATE TRIGGER `tx_no_delete` BEFORE DELETE ON `transactions`
FOR EACH ROW WHEN EXISTS (SELECT 1 FROM `users` WHERE `id` = OLD.`user_id`)
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_NO_DELETE: transactions are voided, never deleted');
