      AND pe.`event_currency` IS NEW.`event_currency` AND pe.`event_amount` IS NEW.`event_amount` AND pe.`event_currency_exponent` IS NEW.`event_currency_exponent`
      AND pe.`merchant_name` IS NEW.`merchant_name` AND pe.`merchant_country` IS NEW.`merchant_country` AND pe.`card_id` IS NEW.`card_id` AND pe.`payment_channel_id` IS NEW.`payment_channel_id`
      AND pe.`transfer_method` IS NEW.`transfer_method` AND pe.`counterparty_kind` IS NEW.`counterparty_kind` AND pe.`counterparty_name` IS NEW.`counterparty_name`
      AND pe.`counterparty_country` IS NEW.`counterparty_country` AND pe.`counterparty_institution` IS NEW.`counterparty_institution` AND pe.`counterparty_account_hint` IS NEW.`counterparty_account_hint`
