-- ---------------------------------------------------------------- transaction_entries
-- Insert order of checks: en_insert_open, en_snapshot_source, en_kind_guard, en_closed_currency.
CREATE TRIGGER `en_immutable` BEFORE UPDATE ON `transaction_entries`
FOR EACH ROW
