  SELECT RAISE(ABORT, 'LEDGER_IMMUTABLE: a transaction entry never changes');
END;--> statement-breakpoint
-- R3 (P7): a closed currency only in a backfill with the user's acknowledgement, or carried over
-- from the same account and currency of the previous version.
CREATE TRIGGER `en_closed_currency` BEFORE INSERT ON `transaction_entries`
FOR EACH ROW WHEN NEW.`currency_status_at_save` = 'closed' AND NOT (
  (NEW.`closed_currency_ack` = 1 AND (SELECT ev.`record_mode` FROM `transaction_events` ev WHERE ev.`id` = NEW.`event_id` AND ev.`user_id` = NEW.`user_id`) IS 'backfill')
  OR EXISTS (SELECT 1 FROM `transaction_entries` c WHERE c.`id` = NEW.`carried_from_entry_id` AND c.`user_id` = NEW.`user_id`
    AND c.`funding_account_id` = NEW.`funding_account_id` AND c.`funding_currency` = NEW.`funding_currency`))
BEGIN
