END;--> statement-breakpoint
-- In a settlement or snapshot correction every entry is carried over and keeps its facts: settlement
-- may only turn a pending amount into a confirmed one, a snapshot correction may only change the
-- jurisdiction snapshot.
CREATE TRIGGER `en_kind_guard` BEFORE INSERT ON `transaction_entries`
FOR EACH ROW WHEN (SELECT ev.`revision_kind` FROM `transaction_events` ev WHERE ev.`id` = NEW.`event_id` AND ev.`user_id` = NEW.`user_id`) IN ('settlement', 'snapshot_correction')
  AND NOT EXISTS (
    SELECT 1 FROM `transaction_entries` c JOIN `transaction_events` ev ON ev.`id` = NEW.`event_id` AND ev.`user_id` = NEW.`user_id`
    WHERE c.`id` = NEW.`carried_from_entry_id` AND c.`user_id` = NEW.`user_id`
      AND c.`direction` IS NEW.`direction` AND c.`funding_account_id` IS NEW.`funding_account_id` AND c.`funding_currency` IS NEW.`funding_currency` AND c.`currency_exponent` IS NEW.`currency_exponent`
      AND CASE ev.`revision_kind`
        WHEN 'settlement' THEN c.`funding_account_country` IS NEW.`funding_account_country`
          AND ((c.`amount_status` IS NEW.`amount_status` AND c.`amount` IS NEW.`amount`) OR (c.`amount_status` = 'pending' AND NEW.`amount_status` = 'confirmed'))
        ELSE c.`amount` IS NEW.`amount` AND c.`amount_status` IS NEW.`amount_status`
