  OR (NEW.`country_source` = 'carried' AND NEW.`funding_account_country` IS NOT (
    SELECT c.`funding_account_country` FROM `transaction_entries` c WHERE c.`id` = NEW.`carried_from_entry_id` AND c.`user_id` = NEW.`user_id`))
  OR (NEW.`carried_from_entry_id` IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM `transaction_entries` c
