    JOIN `transaction_events` ne ON ne.`transaction_id` = ce.`transaction_id` AND ne.`user_id` = ce.`user_id` AND ne.`revision` = ce.`revision` + 1
    WHERE c.`id` = NEW.`carried_from_entry_id` AND c.`user_id` = NEW.`user_id` AND c.`funding_account_id` = NEW.`funding_account_id`
      AND ne.`id` = NEW.`event_id` AND ne.`user_id` = NEW.`user_id`))
  OR (NEW.`carried_from_entry_id` IS NULL AND EXISTS (
    SELECT 1 FROM `transaction_events` ne
