FOR EACH ROW WHEN OLD.`expires_at` IS NULL AND EXISTS (SELECT 1 FROM `users` WHERE `id` = OLD.`user_id`)
BEGIN
  SELECT RAISE(ABORT, 'LEDGER_NO_DELETE: transaction.create idempotency keys are kept');
